<?php use App\Support\Ui; use App\Repositories\CandidateTechnologyRepository as Stack; ?>
<div class="page-heading"><div><a class="back-link" href="<?= $e($url('consultancy/students')) ?>">← Students</a><span class="eyebrow">STUDENT</span><h1><?= $e($student['full_name']) ?></h1><p><?= $e($student['phone']) ?><?php if ($student['experience_years'] !== null): ?> · <?= $e(Stack::yearsText((float) $student['experience_years'])) ?> experience<?php endif; ?></p></div><a class="button primary" href="<?= $e($url('consultancy/book?student_id=' . $student['id'])) ?>"><?= Ui::icon('plus') ?>Book for <?= $e(strtok($student['full_name'], ' ')) ?></a></div>
<section class="card"><div class="card-heading"><div><h2>Tech stack</h2></div></div><?php if ($student['tech_stack']): ?><span class="skill-chips"><?php foreach ($student['tech_stack'] as $skill): ?><span class="skill-chip"><?= $e(Stack::skillLabel($skill)) ?></span><?php endforeach; ?></span><?php else: ?><p class="muted">No tech stack added.</p><?php endif; ?></section>
<?php foreach (['Upcoming interviews' => $upcoming, 'Past interviews' => $past] as $heading => $items): ?>
<section class="card"><div class="card-heading"><div><h2><?= $e($heading) ?></h2></div></div>
<?php if (!$items): ?><p class="muted">None yet.</p><?php else: ?><div class="agenda-list"><?php foreach ($items as $item): ?><a href="<?= $e($url('consultancy/interview?id=' . $item['id'])) ?>" class="agenda-row"><time><?= $e($item['start_local']->format('d M')) ?><br><?= $e($item['start_local']->format('g:i A')) ?></time><span class="agenda-line"></span><div><strong><?= $e($item['company_name']) ?></strong><small><?= $e($item['job_role']) ?> · <?= $e($item['interview_round']) ?> · <?= $e($item['technology_name']) ?></small></div><?= Ui::locationBadge($item) ?><span class="badge <?= $item['interview_type'] === 'TOOL' ? 'purple' : 'neutral' ?>"><?= $e(ucfirst(strtolower($item['interview_type']))) ?></span></a><?php endforeach; ?></div><?php endif; ?>
</section>
<?php endforeach; ?>
